// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        c.XBornID();

        address user = address(0x123);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.getTokens();

        address owner = address(this);
        uint256 ownerBalance = c.balanceOf(address(this));
        assertTrue(ownerBalance == 200000000e18, "Owner balance should be totalDistributed after XBornID");
    }
}
